1	'use client';
2	
3	import React, { useState } from 'react';
4	import { usePortalStore } from '@/lib/store';
5	import PageHeader from '@/components/design-system/PageHeader';
6	import ProgressSteps from '@/components/design-system/ProgressSteps';
7	import Card from '@/components/ui/Card';
8	import Badge from '@/components/ui/Badge';
9	import StickyFooter from '@/components/ui/StickyFooter';
10	import Modal from '@/components/ui/Modal';
11	import CountryFlag from '@/components/ui/CountryFlag';
12	import {
13	  FileText,
14	  Download,
15	  Share2,
16	  Copy,
17	  Check,
18	  Lock,
19	  ArrowRight,
20	  ArrowLeft,
21	  ShieldCheck,
22	  CheckCircle2,
23	  FolderOpen,
24	} from 'lucide-react';
25	
26	const WIZARD_STEPS = [
27	  { label: 'Entity' },
28	  { label: 'Documents' },
29	  { label: 'Upload & KYC' },
30	];
31	
32	export default function VaultPage() {
33	  const { entities, activeEntityId, setActiveEntityId, submitKycHandshake } = usePortalStore();
34	  const activeEntity = entities.find((e) => e.id === activeEntityId) || entities[0];
35	
36	  const [currentStep, setCurrentStep] = useState(0);
37	  const [referenceNumber, setReferenceNumber] = useState(activeEntity?.kycReferenceNumber || '');
38	  const [isSubmitting, setIsSubmitting] = useState(false);
39	  const [handshakeDone, setHandshakeDone] = useState(Boolean(activeEntity?.kycReferenceNumber));
40	  const [shareModalOpen, setShareModalOpen] = useState(false);
41	  const [copied, setCopied] = useState(false);
42	
43	  const totalSteps = WIZARD_STEPS.length;
44	  const isFirstStep = currentStep === 0;
45	  const isLastStep = currentStep === totalSteps - 1;
46	
47	  const handleKycSubmit = (e: React.FormEvent) => {
48	    e.preventDefault();
49	    if (!referenceNumber.trim()) return;
50	    setIsSubmitting(true);
51	    setTimeout(() => {
52	      setIsSubmitting(false);
53	      setHandshakeDone(true);
54	      if (activeEntity) submitKycHandshake(activeEntity.id, referenceNumber);
55	    }, 800);
56	  };
57	
58	  const handleCopy = () => {
59	    navigator.clipboard.writeText(`https://gccstartup.com/v/${activeEntity?.id || 'doc'}-vault?token=sec_9842f`);
60	    setCopied(true);
61	    setTimeout(() => setCopied(false), 2000);
62	  };
63	
64	  if (!activeEntity) {
65	    return (
66	      <div className="flex flex-col items-center text-center py-16 px-6">
67	        <FolderOpen size={40} className="text-muted mb-3" />
68	        <h3 className="text-base font-extrabold text-navy">No Active Entity</h3>
69	        <p className="text-[13px] text-tertiary">Set up a company to access your document vault.</p>
70	      </div>
71	    );
72	  }
73	
74	  const renderStep = () => {
75	    switch (currentStep) {
76	      case 0:
77	        return (
78	          <div className="flex flex-col gap-3 animate-slide-up">
79	            <div className="section-title">Select Entity</div>
80	            {entities.map((ent) => (
81	              <button
82	                key={ent.id}
83	                onClick={() => setActiveEntityId(ent.id)}
84	                className={`card card-hover ${ent.id === activeEntity.id ? 'card-sand border-orange' : ''} flex items-center gap-3 p-3 cursor-pointer`}
85	              >
86	                <CountryFlag country={ent.countryCode} size="md" />
87	                <div className="flex-1 text-left">
88	                  <div className="text-sm font-bold text-navy">{ent.name}</div>
89	                  <div className="text-xs text-tertiary">{ent.jurisdiction}</div>
90	                </div>
91	                {ent.id === activeEntity.id && <Badge variant="orange" size="sm">ACTIVE</Badge>}
92	              </button>
93	            ))}
94	          </div>
95	        );
96	
97	      case 1:
98	        return (
99	          <div className="flex flex-col gap-3 animate-slide-up">
100	            <div className="flex justify-between items-center">
101	              <div className="section-title mb-0">Issued Statutory Files</div>
102	              <Badge variant="info">{activeEntity.documents.length} Files</Badge>
103	            </div>
104	            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
105	              {activeEntity.documents.map((doc) => (
106	                <div key={doc.id} className="card card-hover flex flex-col gap-2 p-3.5">
107	                  <div className="flex justify-between items-center">
108	                    <div className="w-[34px] h-[34px] rounded-lg bg-orange-lt flex items-center justify-center">
109	                      <FileText size={18} className="text-orange" />
110	                    </div>
111	                    <Badge variant={doc.isReady ? 'success' : 'warning'} size="sm">
112	                      {doc.isReady ? 'READY' : 'PENDING'}
113	                    </Badge>
114	                  </div>
115	                  <div>
116	                    <h4 className="text-[13px] font-extrabold text-navy leading-tight">{doc.title}</h4>
117	                    <div className="text-[11px] text-tertiary mt-0.5">{doc.type} - {doc.size}</div>
118	                  </div>
119	                  <div className="mt-auto pt-2 border-t border-border">
120	                    {doc.isReady ? (
121	                      <button
122	                        type="button"
123	                        onClick={() => alert(`Downloading verified copy of ${doc.title}`)}
124	                        className="btn btn-secondary btn-sm w-full text-xs"
125	                      >
126	                        <Download size={13} />
127	                        <span>Download PDF</span>
128	                      </button>
129	                    ) : (
130	                      <div className="text-[11px] text-muted text-center py-1">
131	                        Auto-delivers upon Stage 4
132	                      </div>
133	                    )}
134	                  </div>
135	                </div>
136	              ))}
137	            </div>
138	          </div>
139	        );
140	
141	      case 2:
142	        return (
143	          <div className="flex flex-col gap-4 animate-slide-up">
144	            <div className="section-title">Upload &amp; KYC Handshake</div>
145	
146	            <Card padding="md">
147	              <div className="flex items-center gap-2.5 mb-3">
148	                <div
149	                  className={`w-[38px] h-[38px] rounded-[10px] flex items-center justify-center ${
150	                    handshakeDone
151	                      ? 'bg-success-lt text-success'
152	                      : 'bg-orange-lt text-orange'
153	                  }`}
154	                >
155	                  {handshakeDone ? <CheckCircle2 size={20} /> : <ShieldCheck size={20} />}
156	                </div>
157	                <div>
158	                  <h3 className="text-sm font-extrabold text-navy">
159	                    {handshakeDone ? 'Government Verification Confirmed' : 'Official Portal Identity Handshake'}
160	                  </h3>
161	                  <div className="text-[11px] text-tertiary">
162	                    {handshakeDone
163	                      ? `Registry Reference: ${referenceNumber || activeEntity.kycReferenceNumber}`
164	                      : 'Enter your confirmation reference to advance to Stage 3 Registry Filing'}
165	                  </div>
166	                </div>
167	              </div>
168	
169	              {!handshakeDone ? (
170	                <form onSubmit={handleKycSubmit} className="flex gap-2">
171	                  <input
172	                    type="text"
173	                    placeholder="e.g. IFZA-KYC-2026-849201"
174	                    value={referenceNumber}
175	                    onChange={(e) => setReferenceNumber(e.target.value)}
176	                    className="input-field flex-1"
177	                    required
178	                  />
179	                  <button type="submit" disabled={isSubmitting} className="btn btn-primary shrink-0">
180	                    <span>{isSubmitting ? 'Verifying...' : 'Verify'}</span>
181	                    <ArrowRight size={14} />
182	                  </button>
183	                </form>
184	              ) : (
185	                <div className="p-2.5 rounded-[10px] bg-surface border-l-4 border-l-success text-xs text-secondary">
186	                  Confirmed Reference: <strong className="text-navy">{referenceNumber || activeEntity.kycReferenceNumber}</strong> - Stage 3 is active.
187	                </div>
188	              )}
189	            </Card>
190	
191	            <button
192	              type="button"
193	              onClick={() => setShareModalOpen(true)}
194	              className="btn btn-secondary w-full h-11 text-[13px]"
195	            >
196	              <Share2 size={16} className="text-orange" />
197	              <span>Generate Encrypted Banker Share Link</span>
198	            </button>
199	          </div>
200	        );
201	
202	      default:
203	        return null;
204	    }
205	  };
206	
207	  return (
208	    <div className="flex flex-col gap-5 pb-24">
209	      <PageHeader
210	        eyebrow="SECURE CORPORATE KIT LOCKER"
211	        title="Document Vault"
212	        subtitle="Encrypted statutory repository - manage official commercial certificates and nominee deeds."
213	      />
214	
215	      <div className="card card-sand px-4 py-3">
216	        <ProgressSteps steps={WIZARD_STEPS} currentStep={currentStep} />
217	      </div>
218	
219	      {renderStep()}
220	
221	      <StickyFooter
222	        primaryLabel={isLastStep ? 'Done' : 'Next'}
223	        primaryAction={() => {
224	          if (!isLastStep) setCurrentStep((s) => s + 1);
225	        }}
226	        primaryIcon={isLastStep ? <CheckCircle2 size={16} /> : <ArrowRight size={16} />}
227	        secondaryLabel={isFirstStep ? undefined : 'Back'}
228	        secondaryAction={isFirstStep ? undefined : () => setCurrentStep((s) => s - 1)}
229	      />
230	
231	      <Modal
232	        isOpen={shareModalOpen}
233	        onClose={() => setShareModalOpen(false)}
234	        title="Encrypted Banker Share Link"
235	        badge="SECURE DOSSIER"
236	        badgeVariant="orange"
237	      >
238	        <div className="flex flex-col gap-3.5">
239	          <p className="text-[13px] text-secondary leading-relaxed">
240	            Generate a time-limited 72-hour encrypted viewer link for your corporate banker.
241	          </p>
242	          <div className="card card-sand p-3 flex justify-between items-center gap-2">
243	            <span className="text-[11px] font-mono text-navy overflow-hidden text-ellipsis whitespace-nowrap">
244	              https://gccstartup.com/v/{activeEntity.id}-vault?token=sec_9842f
245	            </span>
246	            <button onClick={handleCopy} className="btn btn-primary btn-sm shrink-0">
247	              {copied ? <Check size={14} /> : <Copy size={14} />}
248	              <span>{copied ? 'Copied' : 'Copy'}</span>
249	            </button>
250	          </div>
251	        </div>
252	      </Modal>
253	    </div>
254	  );
255	}
