1	'use client';
2	
3	import React, { useState } from 'react';
4	import { usePortalStore } from '@/lib/store';
5	import PageHeader from '@/components/design-system/PageHeader';
6	import ProgressSteps from '@/components/design-system/ProgressSteps';
7	import Card from '@/components/ui/Card';
8	import Badge from '@/components/ui/Badge';
9	import StickyFooter from '@/components/ui/StickyFooter';
10	import Modal from '@/components/ui/Modal';
11	import CountryFlag from '@/components/ui/CountryFlag';
12	import {
13	  Clock,
14	  ShieldCheck,
15	  CheckCircle2,
16	  Calendar,
17	  AlertTriangle,
18	  ArrowRight,
19	  ArrowLeft,
20	  Receipt,
21	  FileCheck,
22	  CreditCard,
23	} from 'lucide-react';
24	
25	const WIZARD_STEPS = [
26	  { label: 'Overview' },
27	  { label: 'Payment' },
28	];
29	
30	export default function RenewalsPortalPage() {
31	  const { entities, activeEntityId, setActiveEntityId, payRenewalInvoice } = usePortalStore();
32	  const [currentStep, setCurrentStep] = useState(0);
33	  const [isProcessing, setIsProcessing] = useState(false);
34	  const [isPaidSuccess, setIsPaidSuccess] = useState(false);
35	
36	  const activeEntity = entities.find((e) => e.id === activeEntityId) || entities[0];
37	
38	  const totalSteps = WIZARD_STEPS.length;
39	  const isFirstStep = currentStep === 0;
40	  const isLastStep = currentStep === totalSteps - 1;
41	
42	  const handlePayRenewal = () => {
43	    setIsProcessing(true);
44	    setTimeout(() => {
45	      setIsProcessing(false);
46	      setIsPaidSuccess(true);
47	      if (activeEntity) payRenewalInvoice(activeEntity.id);
48	      setTimeout(() => setIsPaidSuccess(false), 2000);
49	    }, 1000);
50	  };
51	
52	  if (!activeEntity) return null;
53	
54	  const isDueSoon = activeEntity.renewalDaysLeft <= 90;
55	
56	  const renewalCosts = [
57	    { title: 'Official Government Freezone License Renewal Fee', cost: '$1,200 USD', desc: 'Direct government regulatory charge' },
58	    { title: 'Registered Agent & Statutory Office Representation', cost: '$450 USD', desc: 'Mandatory statutory address & legal representative' },
59	    { title: 'Nominee Director & Trustee Shareholder Maintenance', cost: '$800 USD', desc: '12 months nominee deed extension & PoA renewal' },
60	    { title: 'Corporate Banking Good Standing Certificate', cost: 'Included', desc: 'Banker compliance confirmation' },
61	  ];
62	
63	  const renderStep = () => {
64	    switch (currentStep) {
65	      case 0:
66	        return (
67	          <div className="flex flex-col gap-4 animate-slide-up">
68	            <div className="section-title">Select Entity</div>
69	            <div className="flex gap-2 overflow-x-auto pb-1">
70	              {entities.map((ent) => (
71	                <button
72	                  key={ent.id}
73	                  onClick={() => setActiveEntityId(ent.id)}
74	                  className={`btn ${ent.id === activeEntity.id ? 'btn-primary' : 'btn-secondary'} shrink-0 gap-2 text-[13px] py-2 px-4`}
75	                >
76	                  <CountryFlag country={ent.countryCode} size="sm" />
77	                  <span className="max-w-[130px] overflow-hidden text-ellipsis whitespace-nowrap">
78	                    {ent.name}
79	                  </span>
80	                </button>
81	              ))}
82	            </div>
83	
84	            <Card
85	              padding="md"
86	              className={`border-l-4 ${isDueSoon ? 'border-l-orange' : 'border-l-success'}`}
87	            >
88	              <div className="flex justify-between items-center">
89	                <div className="flex items-center gap-3">
90	                  <div
91	                    className={`w-[44px] h-[44px] rounded-xl flex items-center justify-center ${
92	                      isDueSoon ? 'bg-orange-lt text-orange' : 'bg-success-lt text-success'
93	                    }`}
94	                  >
95	                    <Clock size={22} />
96	                  </div>
97	                  <div>
98	                    <div className="text-[11px] font-extrabold text-muted uppercase tracking-wider">
99	                      Renewal Countdown
100	                    </div>
101	                    <h3 className="text-base font-extrabold text-navy">
102	                      {activeEntity.renewalDaysLeft} Days Remaining
103	                    </h3>
104	                    <div className="text-xs text-tertiary">
105	                      Trade License Expiry: {activeEntity.licenseExpiryDate}
106	                    </div>
107	                  </div>
108	                </div>
109	              </div>
110	            </Card>
111	
112	            <div className="section-title">Annual Statutory Breakdown</div>
113	            <div className="flex flex-col gap-2">
114	              {renewalCosts.map((item, idx) => (
115	                <div key={idx} className="card flex justify-between items-center p-3">
116	                  <div>
117	                    <div className="text-[13px] font-bold text-navy">{item.title}</div>
118	                    <div className="text-[11px] text-tertiary">{item.desc}</div>
119	                  </div>
120	                  <strong className="text-[13px] text-orange">{item.cost}</strong>
121	                </div>
122	              ))}
123	            </div>
124	          </div>
125	        );
126	
127	      case 1:
128	        return (
129	          <div className="flex flex-col gap-4 animate-slide-up">
130	            <div className="section-title">Renewal Payment</div>
131	
132	            <Card padding="md">
133	              <p className="text-[13px] text-secondary leading-relaxed mb-3">
134	                Extend the commercial trade license for <strong className="text-navy">{activeEntity.name}</strong> for another 12 months with immediate government priority filing.
135	              </p>
136	
137	              <div className="card card-sand p-3.5 flex justify-between items-center">
138	                <div>
139	                  <div className="text-[11px] text-tertiary">Total Annual Renewal Cost:</div>
140	                  <div className="text-xl font-extrabold text-orange">$2,450 USD</div>
141	                </div>
142	                <Badge variant="success">ALL FEES INCLUDED</Badge>
143	              </div>
144	            </Card>
145	
146	            <div className="card card-sand p-4 border-l-4 border-l-orange">
147	              <div className="flex items-center gap-2 mb-2">
148	                <Clock size={16} className="text-orange" />
149	                <span className="text-xs font-extrabold text-navy">Renewal Details</span>
150	              </div>
151	              <div className="flex flex-col gap-1.5 text-xs text-secondary">
152	                <div className="flex justify-between">
153	                  <span className="text-tertiary">Entity:</span>
154	                  <strong className="text-navy">{activeEntity.name}</strong>
155	                </div>
156	                <div className="flex justify-between">
157	                  <span className="text-tertiary">Current Expiry:</span>
158	                  <strong className="text-navy">{activeEntity.licenseExpiryDate}</strong>
159	                </div>
160	                <div className="flex justify-between">
161	                  <span className="text-tertiary">Days Left:</span>
162	                  <strong className="text-navy">{activeEntity.renewalDaysLeft}</strong>
163	                </div>
164	              </div>
165	            </div>
166	
167	            {isPaidSuccess && (
168	              <div className="card p-3 bg-success-lt border-l-4 border-l-success text-xs text-secondary flex items-center gap-2">
169	                <CheckCircle2 size={16} className="text-success shrink-0" />
170	                <span>Renewal confirmed! Your license has been extended for 12 months.</span>
171	              </div>
172	            )}
173	          </div>
174	        );
175	
176	      default:
177	        return null;
178	    }
179	  };
180	
181	  return (
182	    <div className="flex flex-col gap-5 pb-24">
183	      <PageHeader
184	        eyebrow="STATUTORY CONTINUITY"
185	        title="Annual License Renewals & Maintenance"
186	        subtitle="Ensure uninterrupted corporate legal standing, registered agent service, and banking validity."
187	      />
188	
189	      <div className="flex gap-2 mb-1">
190	        <Badge variant="navy">ANNUAL COMPLIANCE</Badge>
191	      </div>
192	
193	      <div className="card card-sand px-4 py-3">
194	        <ProgressSteps steps={WIZARD_STEPS} currentStep={currentStep} />
195	      </div>
196	
197	      {renderStep()}
198	
199	      <StickyFooter
200	        primaryLabel={isLastStep ? (isPaidSuccess ? 'Confirmed' : 'Authorize $2,450 USD') : 'Next'}
201	        primaryAction={() => {
202	          if (isLastStep && !isPaidSuccess) {
203	            handlePayRenewal();
204	          } else if (!isLastStep) {
205	            setCurrentStep((s) => s + 1);
206	          }
207	        }}
208	        primaryDisabled={isLastStep && (isProcessing || isPaidSuccess)}
209	        primaryLoading={isLastStep && isProcessing}
210	        primaryIcon={isLastStep ? <CreditCard size={16} /> : <ArrowRight size={16} />}
211	        secondaryLabel={isFirstStep ? undefined : 'Back'}
212	        secondaryAction={isFirstStep ? undefined : () => setCurrentStep((s) => s - 1)}
213	        priceLabel={isLastStep ? 'Total' : undefined}
214	        priceValue={isLastStep ? '$2,450' : undefined}
215	        priceSub={isLastStep ? 'All fees included' : undefined}
216	      />
217	    </div>
218	  );
219	}
220

