1	'use client';
2	
3	import React from 'react';
4	import { usePortalStore } from '@/lib/store';
5	import Link from 'next/link';
6	import {
7	  Users,
8	  Clock,
9	  Kanban,
10	  MessageSquare,
11	  ArrowRight,
12	  CheckCircle,
13	  AlertTriangle,
14	} from 'lucide-react';
15	
16	export default function AdminDashboardPage() {
17	  const { entities, whatsappLogs } = usePortalStore();
18	
19	  const activeCount = entities.filter((e) => e.status === 'active').length;
20	  const pendingKyc = entities.filter((e) => e.status === 'official_kyc_pending').length;
21	  const filingCount = entities.filter((e) => e.status === 'filing').length;
22	  const renewalDue = entities.filter((e) => e.renewalDaysLeft < 90).length;
23	
24	  const stats = [
25	    { label: 'Total Entities', value: entities.length, icon: Users, color: 'var(--color-navy)' },
26	    { label: 'Active', value: activeCount, icon: CheckCircle, color: 'var(--color-success)' },
27	    { label: 'KYC Pending', value: pendingKyc, icon: Clock, color: 'var(--color-warning)' },
28	    { label: 'Filing', value: filingCount, icon: Kanban, color: 'var(--color-orange)' },
29	    { label: 'Renewal Due', value: renewalDue, icon: AlertTriangle, color: 'var(--color-error)' },
30	    { label: 'Messages Sent', value: whatsappLogs.length, icon: MessageSquare, color: 'var(--color-info)' },
31	  ];
32	
33	  const quickLinks = [
34	    { href: '/admin/clients', label: 'Client Directory', icon: Users, desc: 'View all entities' },
35	    { href: '/admin/filing-queue', label: 'Filing Queue', icon: Clock, desc: 'Pending actions' },
36	    { href: '/admin/kanban', label: 'Pipeline Board', icon: Kanban, desc: 'Stage management' },
37	    { href: '/admin/whatsapp', label: 'WhatsApp Engine', icon: MessageSquare, desc: 'Send notifications' },
38	  ];
39	
40	  return (
41	    <div className="admin-dashboard">
42	      <div>
43	        <h1 className="admin-page-title">Dashboard</h1>
44	        <p className="admin-page-subtitle">Overview of all operations</p>
45	      </div>
